select round(avg(save_count), 2) as average_saves_per_listing
from (
    select l.item_id, count(s.saved_at) as save_count
    from nlq.listings_all l
    left join nlq.saved_items s on l.item_id = s.item_id
    where l.category = 'electronics'
    group by l.item_id
    having count(s.saved_at) >= 1
) as saved_listings;
